package com.xlox.ui;

import android.view.View;
import android.view.animation.LinearInterpolator;

import com.airbnb.lottie.LottieAnimationView;
import com.airbnb.lottie.LottieDrawable;
import com.xlox.R;

/**
 * 2.3.7: the quiet splash status Lotties (res/raw, generated by
 * scripts/lottie_art.py). 2.3.8: splash only.
 *
 *   arc    anoy_arc    2.4 s loop - "Checking for updates…"
 *   check  anoy_check  0.7 s one-shot, then holds - "Up to date"
 *
 * Reduced motion (animator scale 0): no movement - the arc is one still
 * frame, one-shots show their last frame. Calling the same state again does
 * not restart it, so status refreshes never make it flicker.
 */
public final class Motion {

    private Motion() {
    }

    /** Still frame of the arc under reduced motion. */
    private static final float ARC_STILL = 0f;

    /** Quiet loop while something is in progress. */
    public static void arc(LottieAnimationView view) {
        show(view, R.raw.anoy_arc, true);
    }

    /** One-shot check that draws in and holds. */
    public static void check(LottieAnimationView view) {
        show(view, R.raw.anoy_check, false);
    }

    /** Stops and removes it (GONE) at once. */
    public static void hide(LottieAnimationView view) {
        if (view == null) return;
        view.animate().cancel();
        view.cancelAnimation();
        view.setAlpha(1f);
        view.setVisibility(View.GONE);
        view.setTag(R.id.tag_lottie_res, null);
    }

    private static void show(LottieAnimationView view, int rawRes, boolean loop) {
        if (view == null) return;
        boolean reduced = Ui.reducedMotion(view.getContext());
        boolean same = Integer.valueOf(rawRes).equals(view.getTag(R.id.tag_lottie_res));
        if (view.getVisibility() != View.VISIBLE) {
            // Arrives with its line: a 180 ms fade, like the text beside it.
            view.setVisibility(View.VISIBLE);
            if (!reduced) {
                view.setAlpha(0f);
                view.animate().alpha(1f).setDuration(Ui.SWAP_IN).setInterpolator(new LinearInterpolator()).start();
            }
        }
        if (same && (!loop || reduced || view.isAnimating())) return;
        view.setTag(R.id.tag_lottie_res, rawRes);
        view.cancelAnimation();
        view.setAnimation(rawRes);
        view.setRepeatCount(loop ? LottieDrawable.INFINITE : 0);
        if (reduced) {
            view.setProgress(loop ? ARC_STILL : 1f);
        } else {
            view.setProgress(0f);
            view.playAnimation();
        }
    }
}
